// The disclaimer shown next to law text and diffs: on law pages (built by Astro) and on the
// amendment and versions pages (rendered in the browser), so it is one HTML string both can use.
// The full disclaimer is the "免責事項" section of the about page (#disclaimer); the footer of
// every page carries a short form of it (src/layouts/Base.astro).

export const DISCLAIMER_URL = "/about/#disclaimer";
export const EGOV_URL = "https://laws.e-gov.go.jp/";

/** A short warning that the text and diffs are generated by a program and can be wrong. */
export const DISCLAIMER_NOTE_HTML = `<div role="note" class="alert alert-warning alert-soft mb-4 items-start gap-3 py-2.5 text-base-content" data-disclaimer>
  <svg class="mt-0.5 h-5 w-5 shrink-0 text-warning" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z" /><path d="M12 9v4M12 17h.01" /></svg>
  <p>このページの条文や新旧対照は、プログラムで自動的に生成したものです。変換の誤りや不具合により、表示が崩れたり、誤った内容が表示されたりすることがあります。正式な内容は <a class="link link-primary" href="${EGOV_URL}">e-Gov 法令検索</a> で確認してください。詳しくは<a class="link link-primary" href="${DISCLAIMER_URL}">免責事項</a>をご覧ください。</p>
</div>`;
